reference_solution:
def word_break(s, word_dict):
    words = set(word_dict)
    longest = max(map(len, word_dict))
    possible = [True] + [False] * len(s)
    for end in range(1, len(s) + 1):
        for start in range(max(0, end - longest), end):
            if possible[start] and s[start:end] in words:
                possible[end] = True
                break
    return possible[-1]

